import{_ as n}from"./chunks/icon.B7gRmRZx.js";import{_ as t,a as i,b as r,c as s,d as a,e as o,f as l,g as u,h as d,i as g,j as h}from"./chunks/0.1.12-193-neustart-de.NjH6ArMk.js";import{_ as c,o as p,c as b,a3 as m}from"./chunks/framework.BlfGB29P.js";const D=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.29 mit serverseitiger Funktionsplan-Ausführung und Editoren in DE, EN und FR.","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.29 mit serverseitiger Funktionsplan-Ausführung und Editoren in DE, EN und FR."},"headers":[],"relativePath":"projects/logic-studio/index.md","filePath":"projects/logic-studio/index.md","lastUpdated":1794475309000}'),k={name:"projects/logic-studio/index.md"};function f(A,e,S,z,v,w){return p(),b("div",null,[...e[0]||(e[0]=[m('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+n+`" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – öffentliches Testupdate, 8. November 2026.</strong> Oberfläche und Dokumentation sind jetzt <strong>DE/EN/FR</strong>. Logic Studio ist eine eigene HA-App für grafische Funktionspläne, unabhängig von Grafik Visual Studio und Blocks for HA. Die React-Flow-Zeichenfläche mit eigenen Bausteinen, typgeprüften Verbindungen, Zoom und MiniMap bleibt erhalten; Bibliotheken und Lizenzen sind lokal enthalten.</p><div class="warning custom-block"><p class="custom-block-title">Testversion</p><p>Zuerst auf einem Testsystem installieren und vorher ein vollständiges Backup erstellen. Native Detailoptionen werden zunächst als JSON bearbeitet. Die App schreibt keine Automationen oder Skripte in HA zurück und schaltet keine Geräte. Erzeugte Ausgaben immer prüfen und selbst in HA installieren.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">GitHub-Testrelease und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Quellcode im Sammel-Repository</a></p><h2 id="ha-logic-studio-pro-0-1-29" tabindex="-1">HA Logic Studio Pro 0.1.29 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-29" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.29&quot;">​</a></h2><p>HA Logic Studio Pro ist eine eigenständige Home-Assistant-App im UGSo-Sammelrepository. Sie baut auf Logic Studio auf und greift Erfahrungen aus der Arbeit mit ioBroker auf.</p><p><strong>Verfügbare Funktionen</strong></p><ul><li><strong>Funktionsplan:</strong> Bausteine verbinden, Signale an den Eingängen anzeigen und den Plan simulieren. Die Ausführung auf dem HA-Server kann auf Änderungen reagieren oder in einem festen Zyklus laufen.</li><li><strong>Regeln und Blocks A:</strong> Automationen visuell erstellen und als HA-YAML ausgeben.</li><li><strong>Blocks JS, JavaScript und TypeScript:</strong> Logik bearbeiten, mit simulierten Werten testen und auf dem HA-Server ausführen.</li><li><strong>HA-YAML:</strong> Automationen und Skripte bearbeiten, prüfen und exportieren.</li><li><strong>Projektverwaltung:</strong> Projekte und Ordner pro HA-Benutzer auf dem Server speichern.</li><li><strong>Sprachwahl:</strong> Die Editoren stehen auf Deutsch, Englisch und Französisch zur Verfügung.</li></ul><p><strong>0.1.29</strong> ist das öffentliche Testupdate. Vor dem Update ein Vollbackup erstellen und die Version zuerst auf einem Testsystem ausprobieren.</p><h3 id="was-seit-0-1-12-neu-ist" tabindex="-1">Was seit 0.1.12 neu ist <a class="header-anchor" href="#was-seit-0-1-12-neu-ist" aria-label="Permalink to &quot;Was seit 0.1.12 neu ist&quot;">​</a></h3><ul><li><strong>Projektbaum und Editoren:</strong> Projekte und Ordner werden pro HA-Benutzer serverseitig gespeichert. Vorhandene Browserprojekte können beim ersten Start aus dem bisherigen Browser übernommen werden. JavaScript und TypeScript haben Syntaxfarben, Zeilennummern und eigene Werkzeugleisten. Icons und Farben stimmen zwischen Projektauswahl, Baum und Filtern überein. Blocks A und Blocks JS haben getrennte Filter. Die automatisch bemessene Projektspalte bleibt per Anfasser verstellbar.</li><li><strong>Blocks A und Blocks JS:</strong> Blocks A nutzt den integrierten Katalog von Blocks for HA. Blocks JS hat eine eigene JavaScript-Palette. Blocks A exportiert HA-Automationen als YAML. Blocks JS erzeugt JavaScript für Testlauf und Runtime. Beim ioBroker-Import bleiben unbekannte Blöcke als Platzhalter sichtbar und verhindern die Codeausgabe, bis sie ersetzt sind. ioBroker-Objekt-IDs durch passende HA-Entitäts-IDs ersetzen.</li><li><strong>Funktionsplan:</strong> Simulation, Zeitschritt von einer Sekunde und Zurücksetzen liegen als Icons in der oberen Leiste. Ausgabeformat und Vorschau sind rechts angeordnet. Verbindungen lassen sich am Zieleingang umhängen, Signalwerte erscheinen direkt am Eingang.</li><li><strong>Server-Runtime:</strong> Play startet JavaScript, transpiliertes TypeScript oder Blocks JS auf dem HA-Server. Stopp und Neustart sind im Editor verfügbar. Status und Runtime-Protokoll bleiben beim Browserwechsel abrufbar. Der separate <strong>Testlauf</strong> verwendet simulierte Zustände und Ereignisse. HA-YAML-Skripte und -Automationen werden exportiert und anschließend in Home Assistant ausgeführt.</li></ul><h3 id="live-runtime-einrichten" tabindex="-1">Live-Runtime einrichten <a class="header-anchor" href="#live-runtime-einrichten" aria-label="Permalink to &quot;Live-Runtime einrichten&quot;">​</a></h3><p>In <strong>Einstellungen → Apps → HA Logic Studio Pro → Konfiguration</strong> die benötigten Einträge setzen, speichern und die App neu starten. Die Listen sind anfangs leer. Beispiel für einen eigens angelegten Testhelfer:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Eine Schreibfreigabe erlaubt auch das Lesen. <code>ha.readState</code> und <code>ha.readAttribute</code> liefern die zuletzt von HA bestätigten Werte. <code>ha.onState</code>, <code>ha.onAttribute</code> und <code>ha.onEvent</code> reagieren auf freigegebene Änderungen und Ereignisse. <code>ha.callAction</code> unterstützt Schaltaktionen, Werte für Zahlen-, Text- und Auswahlhelfer sowie Taster mit genau einem freigegebenen Ziel. <code>ha.schedule</code> verarbeitet Zeitmuster und feste Uhrzeiten mit optionalen Wochentagen in der HA-Zeitzone.</p><p>Nach einem App-Neustart müssen Skripte erneut gestartet werden. Bei einer Verbindungsunterbrechung oder abgelehnten Aktion hält die Runtime das Skript an und protokolliert den Fehler. Astro-Auslöser und automatische Wiederverbindung sind offen.</p><p><strong>Geprüft auf .193 mit HA 2026.11.1:</strong> Live-Zustand und Attribut gelesen, Testhelfer per Zeitplan eingeschaltet und per echtem HA-Ereignis ausgeschaltet. Beide Zustandswechsel wurden gemeldet. Ein importierter Blocks-JS-Zeitplan lief alle zwei Sekunden. Zuvor wurden Start, Stopp, Neustart und der Weiterlauf nach Verlassen der Studio-Seite mit JavaScript und TypeScript geprüft.</p><h3 id="_0-1-29-·-manuelles-speichern-und-blocks-editoren" tabindex="-1">0.1.29 · Manuelles Speichern und Blocks-Editoren <a class="header-anchor" href="#_0-1-29-·-manuelles-speichern-und-blocks-editoren" aria-label="Permalink to &quot;0.1.29 · Manuelles Speichern und Blocks-Editoren&quot;">​</a></h3><p>Alle Editoren übernehmen Änderungen erst mit <strong>Speichern</strong>. <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand oder verwirft ein neues Projekt. Bei ungespeicherten Änderungen sind <strong>Play</strong> und <strong>Neustart</strong> gesperrt. Ein laufendes Skript lässt sich weiterhin stoppen. Blocks A öffnet die Entitätsauswahl direkt am Blockfeld. Blocks JS bietet eine an ioBroker orientierte Palette mit HA-Entitäten, HA-Aktionen und Auslösern ohne Jinja.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.29" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><h3 id="_0-1-28-·-ubersetzungen-in-den-editoren" tabindex="-1">0.1.28 · Übersetzungen in den Editoren <a class="header-anchor" href="#_0-1-28-·-ubersetzungen-in-den-editoren" aria-label="Permalink to &quot;0.1.28 · Übersetzungen in den Editoren&quot;">​</a></h3><p>Version <strong>0.1.28</strong> ergänzt die Übersetzungen für Regeln, Blocks A, Blocks JS, JavaScript, TypeScript und HA-YAML. Die Sprachwahl gilt auch für den Funktionsplan. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.28" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><p>Auf .193 wurden die Werkzeugleisten von Funktionsplan, Regeln, Blocks A, Blocks JS, JavaScript, TypeScript, HA-Automation und HA-Skript im Browser in allen drei Sprachen geprüft. Zusätzlich wurde der französische Dialog für Codebeispiele geprüft.</p><p>Für die Installation im App-Store des UGSo-Sammelrepositories <strong>HA Logic Studio Pro</strong> auswählen. Bei einer bestehenden GitHub-Installation nach Updates suchen und <strong>HA Logic Studio Pro → Aktualisieren</strong> wählen. Mit <strong>DE</strong>, <strong>EN</strong> und <strong>FR</strong> oben in der Projektleiste wechselt die Sprache der Editoren.</p><h3 id="_0-1-26-·-fbd-runtime" tabindex="-1">0.1.26 · FBD Runtime <a class="header-anchor" href="#_0-1-26-·-fbd-runtime" aria-label="Permalink to &quot;0.1.26 · FBD Runtime&quot;">​</a></h3><p>Funktionsplan direkt über <strong>Play</strong> auf dem HA-Server starten. <strong>Automatisch</strong> reagiert auf Änderungen der freigegebenen Zustände und Attribute; <strong>Fester Zyklus</strong> wertet den Plan alle 100 bis 60.000 ms aus. Simulation und YAML-Ausgabe bleiben separat. <strong>Speichern</strong> übernimmt den Entwurf, <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand. Die Werkzeugleiste ist in DE/EN/FR verfügbar.</p><p>Auf .193 schaltete der Automatikstart den Testhelfer ein; der 200-ms-Zyklus schaltete ihn wieder aus. Stopp und das Verwerfen einer ungespeicherten Änderung wurden ebenfalls geprüft. Die Reaktion auf Eingangsänderungen wurde zusätzlich lokal für beide Betriebsarten getestet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.26" target="_blank" rel="noreferrer">GitHub-Testupdate und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">App im Sammelrepository</a></p><h2 id="testinstallation-aus-github" tabindex="-1">Testinstallation aus GitHub <a class="header-anchor" href="#testinstallation-aus-github" aria-label="Permalink to &quot;Testinstallation aus GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Repository in Home Assistant hinzufügen"></a></p><ol><li>In <strong>Einstellungen → Apps → App-Store → Repositorys</strong> die folgende Adresse eintragen. Ist „UGSo HA Apps“ schon eingerichtet, nur nach Updates suchen.</li><li><strong>UGSo Logic Studio</strong> auswählen und installieren. Falls experimentelle Apps ausgeblendet sind, im HA-Profil den erweiterten Modus aktivieren.</li><li>Starten und die Benutzeroberfläche öffnen. Unterstützt werden <strong>HA OS/Supervised</strong>, <strong>amd64 und aarch64</strong>. Der erste Container-Build kann einige Minuten dauern. Dies ist kein HACS-/Marketplace-Frontend-Paket.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Vorhandene lokale Testinstallation erhalten:</strong> GitHub- und lokale App haben verschiedene Repository-IDs und getrennte Daten. Den alten Plan über <strong>Projekt</strong> als JSON exportieren und in der GitHub-App über <strong>Öffnen</strong> importieren. Es gibt keine automatische Migration oder Deinstallation. Projekt und Paletteinstellungen der jeweiligen App bleiben unter <code>/data</code> gespeichert.</p><p><strong>Bestehende GitHub-App aktualisieren:</strong> Vorher sichern, in der App-Verwaltung nach Updates suchen und <strong>UGSo Logic Studio → Aktualisieren</strong> wählen. Die App bleibt installiert; <code>/data</code>, Entity-IDs und bestehende Pläne werden nicht ersetzt. Nicht deinstallieren oder die App-ID wechseln. Auf .193 blieben Originalplan, Favoriten, zuletzt benutzte Bausteine und eingeklappte Bereiche nach dem Update erhalten.</p><h2 id="sprache-werkzeugleiste-und-dokumentation" tabindex="-1">Sprache, Werkzeugleiste und Dokumentation <a class="header-anchor" href="#sprache-werkzeugleiste-und-dokumentation" aria-label="Permalink to &quot;Sprache, Werkzeugleiste und Dokumentation&quot;">​</a></h2><p>Oben <strong>Sprache → Deutsch / English / Français</strong> wählen. Menüs, Bausteinbeschreibungen, Entitätsauswahl sowie Import-/Exportdialoge wechseln ohne Neuladen. Die Auswahl wird mit den Browser-/App-Einstellungen gespeichert. <strong>Eigene Namen, Entitäts-IDs, Werte, Anschlussbezeichnungen und erzeugter YAML-/JavaScript-Code werden nicht übersetzt.</strong></p><p><strong>Dokumentation</strong> rechts zeigt die tatsächlich unterstützten Tastenkürzel und bei ausgewähltem Baustein dessen Beschreibung sowie Ein-/Ausgänge. <strong>Strg+Z / Strg+Y</strong>: Rückgängig/Wiederholen; <strong>Entf</strong>: Auswahl löschen; <strong>Esc</strong>: Verbindung abbrechen/Menü schließen. Anschlüsse lassen sich mit Tab und Enter/Leertaste auswählen und verbinden. Debugger-Befehle des ioBroker-Referenzeditors werden nicht als verfügbare Funktionen dargestellt.</p><p>Die Werkzeugleiste gruppiert <strong>Rückgängig/Wiederholen → Projekt → Simulation → Ausgabe</strong>. Die drei Simulationsbuttons sind gleich groß und einzeln erkennbar. Das Projektmenü enthält zusätzlich <strong>Neues Projekt</strong> und <strong>Beispiel laden</strong>. Die Entitätsauswahl öffnet über das Icon <strong>neben HA-Entity-ID</strong> in den Eigenschaften von STATE_IN/STATE_OUT; der bisherige obere Auswahlbutton entfällt.</p><p><img src="`+t+'" alt="Deutsche Dokumentationsansicht auf .193 mit unverändertem Plan"></p><p><img src="'+i+'" alt="Englische Dokumentationsansicht desselben Plans auf .193"></p><p><img src="'+r+'" alt="Französische Dokumentationsansicht desselben Plans auf .193"></p><h2 id="zwei-arten-von-planen" tabindex="-1">Zwei Arten von Plänen <a class="header-anchor" href="#zwei-arten-von-planen" aria-label="Permalink to &quot;Zwei Arten von Plänen&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Plan</th><th>Zweck und Ausgabe</th></tr></thead><tbody><tr><td>Wertplan</td><td>Typisierte Ein-/Ausgänge, Logik, Mathematik, Auswahl sowie Speicher, Flanken, Timer und Zähler. 33 implementierte Typen; weitere Referenztypen sind als Vorlagen gekennzeichnet. Ausgabe als HA-Automation, HA-Skript oder JavaScript-Funktion mit Host-Schnittstelle.</td></tr><tr><td>Nativer HA-Ablauf</td><td>Automationen, Skripte und Blueprints importieren und als verschachtelte Bausteine bearbeiten. 53 zusätzliche HA-Typen für Auslöser, Bedingungen, Zweige, Schleifen, Warteaktionen, Variablen und Blueprint-Eingaben. Ausgabe ausschließlich als native HA-YAML.</td></tr></tbody></table></div><p>Wertpläne können mit Demo-/Momentaufnahmewerten simuliert werden. Persistente Wertbausteine benötigen die dokumentierten HA-Texthelfer bzw. einen JavaScript-Speicher-Host. Native HA-Abläufe werden im Editor weder ausgeführt noch automatisch in JavaScript umgerechnet. Die JavaScript-Ausgabe ist kein ioBroker-Skript.</p><h2 id="verbindungen-ziehen-und-miniubersicht" tabindex="-1">Verbindungen ziehen und Miniübersicht <a class="header-anchor" href="#verbindungen-ziehen-und-miniubersicht" aria-label="Permalink to &quot;Verbindungen ziehen und Miniübersicht&quot;">​</a></h2><p>Am farbigen Anschluss die Maustaste gedrückt halten, zum passenden Gegenanschluss ziehen und loslassen. Der Cursor wird zum Kreuz; eine Leitungsvorschau folgt der Maus. Passende Ziele werden grün, unpassende oder belegte Eingänge rot markiert. Auch vom Eingang zurück zum Ausgang ziehen ist möglich. <strong>Esc</strong> oder Loslassen auf freier Fläche bricht ab; <strong>Rückgängig</strong> nimmt eine erstellte Leitung zurück.</p><p><strong>BOOL verbindet nur mit BOOL.</strong> Gleiche Signaltypen passen zueinander; <code>INT → REAL</code> ist zusätzlich erlaubt. Explizite <code>ANY</code>-Anschlüsse sind universell. Zahlen und Texte werden nicht stillschweigend zu BOOL umgedeutet. Pro Eingang ist genau eine Leitung erlaubt; falsche Typen, gleiche Anschlussseiten, Selbstverbindungen und Rückkopplungen werden abgewiesen. Eine Fehlermeldung erklärt den Grund. Für die Tastatur Ausgang per Tab/Enter auswählen, anschließend Eingang und Enter.</p><p><img src="'+s+'" alt="Auf .193 erfolgreich mit der Maus verbundene BOOL-Anschlüsse"></p><p><img src="'+a+'" alt="STRING nach BOOL wird mit verständlichem Typfehler abgewiesen"></p><p>Rechts unten zeigt die <strong>MiniMap</strong> farbige Bausteinpositionen und den sichtbaren Ausschnitt. In der MiniMap ziehen zum Navigieren und das Mausrad zum Zoomen verwenden. Auf der freien Zeichenfläche ziehen verschiebt den Ausschnitt; <strong>+/−</strong> ändern den Zoom, <strong>Alles anzeigen</strong> passt alle Bausteine ein. Bausteine am Kopf verschieben. Der Herkunftslink <strong>React Flow</strong> bleibt unten rechts sichtbar. Seit 0.1.8 läuft die Bibliothek tatsächlich im Editor; Fachlogik, Typprüfung und Exporte bleiben eigenständige Logic-Studio-Funktionen.</p><p><img src="'+o+'" alt="React-Flow-Zeichenfläche mit erhaltenem Originalplan und MiniMap auf .193"></p><p><img src="'+l+'" alt="Lokaler React-Flow-Test mit typisierten Bausteinen"></p><p>Die folgenden Bilder dokumentieren zusätzlich die vorherigen Tests mit 0.1.7.</p><p><img src="'+u+'" alt="Miniübersicht mit Bausteinpositionen und sichtbarem Ausschnitt auf .193"></p><h2 id="import-und-bearbeitung" tabindex="-1">Import und Bearbeitung <a class="header-anchor" href="#import-und-bearbeitung" aria-label="Permalink to &quot;Import und Bearbeitung&quot;">​</a></h2><p><strong>HA importieren</strong> öffnen, Automationen/Skripte/Blueprints auswählen und <strong>Aus HA einlesen</strong>, eine YAML-/JSON-Datei oder eingefügten Text verwenden. Eintrag und Vorschau prüfen, dann <strong>Import übernehmen</strong>. Vorher den eigenen Plan als JSON sichern; zusätzlich entstehen Projekt- und Quelldateisicherungen.</p><p>Der HA-Konfigurationsordner ist <strong>schreibgeschützt</strong> eingebunden. Gelesen werden <code>automations.yaml</code>, <code>scripts.yaml</code> und Blueprint-Dateien. Vor dem Parsen kopiert die App Quellen unter <code>/data/ha-source-backups/&lt;Zeitstempel&gt;/</code> mit ursprünglichem Namen. <code>secrets.yaml</code> wird nicht geöffnet; <code>!secret</code> und <code>!include</code> bleiben unaufgelöst. Bei ausgelagerten Include-Dateien die tatsächliche Datei selbst importieren.</p><p>Orange <strong>FLOW</strong>-Leitungen bilden Reihenfolge und Zweige ab: Zweigausgang → <strong>DO</strong>, anschließend <strong>NEXT → DO</strong>. Gelbe <strong>VALUE/REF</strong>-Leitungen zeigen Blueprint-Parameter und deren <code>!input</code>-Verwendung. Eigenschaften enthalten HA-Konfiguration und Zweigpfade als JSON. Parameter-/Feldschlüssel müssen eindeutig sein. Unbekannte Abschnitte bleiben als <strong>YAML_ORIGINAL</strong> erhalten; fehlende Verbindungen können den Export sperren.</p><p><img src="'+d+'" alt="Importvorschau vorhandener HA-Blueprints"></p><p>Das <strong>⋮-Menü</strong> jedes Bausteins bietet <strong>Eigenschaften, Duplizieren und Löschen</strong>. Duplizieren übernimmt Eigenschaften ohne Leitungen. Löschen entfernt zugehörige Leitungen; <strong>Rückgängig</strong> stellt sie wieder her. Suche, Favoriten und zuletzt benutzte Bausteine erleichtern die Auswahl.</p><p><img src="'+g+'" alt="Drei-Punkte-Menü im Funktionsplan"></p><h2 id="prufstand-und-grenzen" tabindex="-1">Prüfstand und Grenzen <a class="header-anchor" href="#prufstand-und-grenzen" aria-label="Permalink to &quot;Prüfstand und Grenzen&quot;">​</a></h2><p><strong>0.1.12 auf .193 / HA Core 2026.10.4:</strong> Nach Vollbackup die lokale App von 0.1.8 aktualisiert. DE/EN/FR, Dokumentationsansicht und reale Entitätsauswahl erfolgreich geprüft. Französisch blieb nach Browser-Neuladen, App-Neustart und erneutem Laden des gespeicherten App-Projekts erhalten; abschließend wieder Deutsch eingestellt. Der Vergleich der Projektdateien zeigt <strong>nur die neue Versionsnummer</strong>, alle fünf Bausteine, drei Verbindungen, Namen, Werte und Positionen sind identisch. Der erzeugte YAML-Code ist in EN und FR identisch. Keine Geräte geschaltet. <strong>31 Node- und neun Python-Tests</strong> bestanden. Die folgenden älteren Berichte bleiben als Historie erhalten.</p><p><img src="'+h+'" alt="Deutsch nach erfolgreichem App-Neustart auf .193"></p><p><strong>0.1.8 auf .193 / HA Core 2026.10.4:</strong> Bestehende lokale App nach Vollbackup aktualisiert. BOOL-Verbindungen per Maus, STRING→BOOL-Abweisung, belegte Eingänge, Verschieben/Rückgängig, Duplizieren, Zoom und MiniMap bestanden. Die Entitätsauswahl liest HA-Entitäten; ein verschachteltes Skript mit If/Then/Else, Delay und Stop wurde importiert und strukturerhaltend ausgegeben. Danach Originalplan wiederhergestellt und nach Neuladen verglichen: <strong>alle IDs, Positionen, Parameter und drei Leitungen unverändert</strong>, ebenso Favoriten, zuletzt benutzt und eingeklappte Kategorien. Keine Geräte geschaltet. Docker-Build und Container-HTTP-Test erfolgreich; <strong>29 Node- und acht Python-Tests</strong> bestanden. Bilder zeigen die deutsche Oberfläche. Hell-/Dunkel-Wechsel wurde in diesem Schritt nicht erneut manuell geprüft.</p><p>Der Funktionsstand <strong>0.1.5</strong> wurde auf <strong>.193 / HA Core 2026.10.4</strong> geprüft: echter Blueprint-Import, Automation-/Skript-/Blueprint-Beispiele, inhaltlich gleiche YAML-Ausgabe und Menüaktionen. <strong>0.1.6</strong> ist dessen erste öffentliche Paketierung. 22 Node- und acht Python-Tests prüfen unter anderem Export, Persistenz, verschachtelte Abläufe und sicheren Quelldateiimport; die GitHub-Prüfung baut zusätzlich den Container.</p><p><strong>0.1.7 auf .193 / HA Core 2026.10.4:</strong> Echter Maus-Ziehtest für BOOL → BOOL und die Gegenrichtung bestanden. STRING → BOOL und ein bereits belegter Eingang wurden abgewiesen. Miniübersicht, Klicknavigation und Pos1 geprüft. Nach dem Test wurde der Originalplan wiederhergestellt und mit der Sicherung verglichen: <strong>fünf Bausteine, drei Leitungen und alle Paletteinstellungen erhalten</strong>, einschließlich nach dem lokalen Update auf 0.1.7. Vorher vollständiges HA-Backup und separate Plan-/Einstellungssicherung; keine Geräte geschaltet. Aktuell bestehen <strong>26 Node- und acht Python-Tests</strong>. Bilder zeigen die deutsche Oberfläche.</p><p>Keine vollständige HA-Semantikprüfung im Editor: Ziele, Templates und Selektoren in HA kontrollieren. Kommentare, YAML-Anker und Formatierung werden nicht originalgetreu rekonstruiert. Importgrenzen: <strong>1 MB, 200 Bausteine, 500 Leitungen</strong>, begrenzte Verschachtelung und bis zu 250 Blueprint-Dateien in üblichen Ordnern. Regler, Kalender und eigene Unterpläne sind teilweise noch Vorlagen.</p><p>Für lokale Tests das Release-ZIP vollständig entpacken, Python 3.10+ und die Pakete aus <code>requirements.txt</code> installieren; unter Windows danach <strong>Start-Demo.cmd</strong> starten. <code>http://127.0.0.1:4180/</code> zeigt Demo-Entitäten ohne HA-Verbindung. Das ZIP enthält außerdem <code>addon/logic_studio/</code> für lokale App-Installationen.</p><p>Fehler bitte mit Versionen, Architektur und einem kleinen anonymisierten Beispiel <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">auf GitHub melden</a>. Keine Zugangsdaten, persönlichen Automationen oder Vollbackups veröffentlichen. Weitere Anleitungen und Prüfbericht liegen im Paket. Lizenz: MIT; Herkunft der übernommenen Block-Metadaten siehe <code>THIRD-PARTY.txt</code>.</p>',70)])])}const _=c(k,[["render",f]]);export{D as __pageData,_ as default};
